# Lore test-command interface (lore_list_tests / lore_run_test).
# Written for this repo's Jest suite rather than adapted from the Vitest
# equivalent for a Vitest suite: the report shapes happen to match, but the
# invocations do not.
- id: hal-engine-jest
  name: HAL Engine Jest suite
  cwd: .
  description: >-
    The ts-jest unit suite over src/ and scripts/ (jest.config.js roots), run
    on every pull request in .github/workflows/ci.yml as the "Test" step.
    Selectors are "<repo-relative-file>::<full test name>" as emitted by the
    list command. Jest has no dry-run, so the list command executes the suite
    once with --json and derives every name from the report; it deliberately
    tolerates a red suite, since listing must not depend on the tests passing.
    The run command selects one test with --runTestsByPath plus an anchored,
    regex-escaped -t, and treats a selector that matches nothing as a failure
    rather than a green run of an empty suite. Neither command builds first:
    no test here reads dist/.
  list: node scripts/lore-list-tests.mjs
  run: node scripts/lore-run-test.mjs "{selector}"
  coverage_format: lcov
import {validateMessage} from './validation.js';

// spec: specs/hal-engine-websocket-protocol/spec.md#214
it('accepts list_sessions paging values and rejects malformed fields', () => {
  const before = {sessionId: 'session-1', updatedAt: '2026-10-28T10:00:00.000Z'};

  const cursors = [before.updatedAt, 0].map(updatedAt => ({...before, updatedAt}));
  const paging = [0, 1, 201].flatMap(limit => cursors.map(cursor => ({limit, before: cursor})));
  const accepted = [{type: 'list_sessions'}, ...paging.map(fields => ({type: 'list_sessions', ...fields}))];
  const malformed = [
    ...[-1, 1.5, '10', null, Infinity, NaN].map(limit => ({field: 'limit', payload: {type: 'list_sessions', limit}})),
    ...[
      null,
      [],
      'yesterday',
      {},
      {...before, sessionId: ''},
      {...before, sessionId: 's'.repeat(129)},
      {...before, updatedAt: 'not a date'},
      {...before, updatedAt: Infinity},
      {...before, updatedAt: 1e20},
    ].map(cursor => ({field: 'before', payload: {type: 'list_sessions', before: cursor}})),
  ];
  expect({
    accepted: accepted.map(payload => validateMessage({...payload, userId: 'other', extra: true})),
    rejected: malformed.map(({field, payload}) => {
      const result = validateMessage(payload);
      return !result.valid && result.error.includes(field);
    }),
    cursors: paging.map(fields =>
      validateMessage({type: 'list_sessions', ...fields, before: {...fields.before, extra: true}})
    ),
  }).toEqual({
    accepted: accepted.map(data => ({valid: true, data})),
    rejected: malformed.map(() => true),
    cursors: paging.map(fields => ({valid: true, data: {type: 'list_sessions', ...fields}})),
  });
});
import type {SessionEntry} from './session.js';

export interface UserMessagePayload {
  type: 'user_message';
  content: string;
}

export interface PingMessage {
  type: 'ping';
  timestamp: number;
}

export interface ListSessionsMessage {
  type: 'list_sessions';
  limit?: number;
  before?: {sessionId: string; updatedAt: string | number};
}

export type IncomingMessage = UserMessagePayload | PingMessage | ListSessionsMessage;

export interface ConnectedMessage {
  type: 'connected';
  sessionId: string;
  message: string;
  examplePrompts: string[];
  resumed?: boolean;
  entryCount?: number;
  /** Why a named id was not rejoined: `expired` only for the session's own owner, `unknown` for every other case. */
  resumeFailure?: 'expired' | 'unknown';
}

export interface EntryUpsertMessage {
  type: 'entry_upsert';
  index: number;
  entry: SessionEntry;
}

export interface EntryDeltaMessage {
  type: 'entry_delta';
  index: number;
  delta: string;
}

export interface EntryCommitMessage {
  type: 'entry_commit';
  index: number;
}

export interface ErrorMessage {
  type: 'error';
  code: string;
  message: string;
}

export interface PongMessage {
  type: 'pong';
  timestamp: number;
}

export interface EntrySkipMessage {
  type: 'entry_skip';
  index: number;
}

export interface StreamEndMessage {
  type: 'stream_end';
}

export type OutgoingMessage =
  | ConnectedMessage
  | EntryUpsertMessage
  | EntryDeltaMessage
  | EntryCommitMessage
  | EntrySkipMessage
  | ErrorMessage
  | PongMessage
  | StreamEndMessage;

export {ErrorCodes} from './session.js';
